# Shared by the macOS and Windows runtime builds. Keep every decoder, demuxer,
# protocol and hardware accelerator from the platform's existing configuration.
# Only MP3 encoding is used by the application. Test fixtures are generated by a
# separate full FFmpeg executable that is never copied into application packages.
playback_options=(
  --disable-encoders
  --enable-encoder=libmp3lame
  --disable-librav1e --disable-libsvtav1 --disable-libkvazaar --disable-libvvenc
)
